import {travelCalc,round} from './calc.mjs';
export function monthBounds(month){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||+month.slice(0,4)<1900)return null;const first=month+'-01',d=new Date(first+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);d.setUTCDate(0);return {from:first,to:d.toISOString().slice(0,10)};}
export function filledTravel(t){return {...t,liters:round(Number(t.startFuel)+Number(t.refill)-Number(t.endTarget)),fuelMode:'filled'};}
export function previousMonthRecord(records,t){const date=new Date(t.from+'T12:00:00Z');if(!Number.isFinite(+date))return null;date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()-1);const month=date.toISOString().slice(0,7);return records.filter(row=>row.from.slice(0,7)===month&&row.car.trim().toUpperCase()===t.car.trim().toUpperCase()&&(!t.plate||!row.plate||row.plate.trim().toUpperCase()===t.plate.trim().toUpperCase())).sort((a,b)=>Number(!!b.plate)-Number(!!a.plate)||b.to.localeCompare(a.to))[0]||null;}
export const fraction=(rate,liters)=>Number.isFinite(rate)&&Number.isFinite(liters)?`${Math.round(rate)}/${Math.round(liters)}`:'—';
export function fuelMetrics(t){const r=travelCalc(t),real=t.realKm===''||t.realKm==null?null:Number(t.realKm);return {...r,realKm:real,realDifference:real!==null&&r.total>0?round(real-r.total):null,realPercent:real!==null&&r.total>0?round((real-r.total)/r.total*100):null,deviation:r.normFuel>0?round(Math.abs(t.liters-r.normFuel)/r.normFuel*100,4):null,realRate:real>0?round(t.liters/real*100,4):null};}
export function validFuel(t){return t&&typeof t.car==='string'&&t.car.trim()&&t.car.length<120&&typeof t.plate==='string'&&t.plate.length<40&&/^\d{4}-\d{2}-\d{2}$/.test(t.from)&&/^\d{4}-\d{2}-\d{2}$/.test(t.to)&&t.to>=t.from&&['liters','rate','odometer','startFuel','endTarget'].every(k=>Number.isFinite(t[k])&&t[k]>=0)&&Number.isFinite(t.adjustmentKm||0)&&(t.realKm===''||t.realKm==null||Number.isFinite(t.realKm)&&t.realKm>=0)&&Array.isArray(t.rows)&&t.rows.length>0&&t.rows.length<=5&&t.rows.every(row=>Number.isFinite(row.km)&&row.km>=0&&typeof row.route==='string'&&typeof row.date==='string')&&!travelCalc(t).error;}
